INSERT INTO `SERVMASK_PREFIX_options` VALUES (166,'theme_mods_realtor-raihan','a:21:{i:0;b:0;s:18:\"nav_menu_locations\";a:1:{s:7:\"primary\";i:7;}s:18:\"custom_css_post_id\";i:96;s:16:\"sidebars_widgets\";a:2:{s:4:\"time\";i:1795068433;s:4:\"data\";a:1:{s:19:\"wp_inactive_widgets\";a:5:{i:0;s:7:\"block-2\";i:1;s:7:\"block-3\";i:2;s:7:\"block-4\";i:3;s:7:\"block-5\";i:4;s:7:\"block-6\";}}}s:8:\"rr_phone\";s:16:\"+971 52 102 7252\";s:11:\"rr_whatsapp\";s:12:\"971521027252\";s:8:\"rr_email\";s:23:\"hello@realtorraihan.com\";s:7:\"rr_area\";s:10:\"Dubai, UAE\";s:15:\"rr_blog_eyebrow\";s:14:\"Property notes\";s:13:\"rr_blog_title\";s:45:\"Dubai property,\r\nexplained <em>properly.</em>\";s:12:\"rr_blog_lede\";s:219:\"Service charges, yields, payment plans, handover snags and the paperwork nobody warns you about. These are the notes I would send a friend before they buy. Short, specific, and written from deals I have actually closed.\";s:12:\"rr_blog_hero\";s:22:\"skyline-dusk-wide.webp\";s:18:\"rr_blog_list_title\";s:54:\"Discover our latest Dubai\r\nproperty <em>insights.</em>\";s:13:\"rr_news_title\";s:37:\"One note a month,\r\n<em>no noise.</em>\";s:12:\"rr_news_text\";s:136:\"A short email with what actually moved in the Dubai market, plus one thing worth knowing before your next viewing. Unsubscribe any time.\";s:12:\"rr_logo_mark\";s:100:\"https://bagheeraventures.com/realtorraihan/wp-content/uploads/2026/11/realtor-raihan-logo-lockup.png\";s:14:\"rr_logo_lockup\";s:100:\"https://bagheeraventures.com/realtorraihan/wp-content/uploads/2026/11/realtor-raihan-logo-lockup.png\";s:14:\"rr_founder_img\";i:93;s:12:\"rr_brand_sub\";s:10:\"Dubai, UAE\";s:18:\"rr_footer_keywords\";s:3197:\"Property Consultant in Downtown Dubai\nProperty Consultant in Dubai Marina\nReal Estate Agent in Dubai Marina\nProperty Consultant in Palm Jumeirah\nBuy Property in Palm Jumeirah\nProperty Consultant in Business Bay\nProperty Consulting Services in Business Bay\nProperty Consultant in Jume