INSERT INTO `SERVMASK_PREFIX_options` VALUES (347,'rr_home_hero_lede','I\'m a professional property consultant in Dubai who helps people buy, sell, rent and invest with confidence. You get straight answers, real numbers, and someone who picks up the phone.','auto');
