INSERT INTO `SERVMASK_PREFIX_options` VALUES (412,'rr_blog_page','a:14:{s:7:\"eyebrow\";s:14:\"Property notes\";s:5:\"title\";s:45:\"Dubai property,\r\nexplained <em>properly.</em>\";s:4:\"lede\";s:219:\"Service charges, yields, payment plans, handover snags and the paperwork nobody warns you about. These are the notes I would send a friend before they buy. Short, specific, and written from deals I have actually closed.\";s:8:\"hero_img\";s:22:\"skyline-dusk-wide.webp\";s:8:\"list_tag\";s:4:\"Blog\";s:10:\"list_title\";s:54:\"Discover our latest Dubai\r\nproperty <em>insights.</em>\";s:10:\"filter_all\";s:3:\"All\";s:9:\"read_more\";s:13:\"Read the note\";s:9:\"empty_msg\";s:48:\"No articles yet. Add your first one under Posts.\";s:10:\"news_title\";s:37:\"One note a month,\r\n<em>no noise.</em>\";s:9:\"news_text\";s:136:\"A short email with what actually moved in the Dubai market, plus one thing worth knowing before your next viewing. Unsubscribe any time.\";s:16:\"news_placeholder\";s:15:\"you@example.com\";s:8:\"news_btn\";s:9:\"Subscribe\";s:9:\"news_note\";s:40:\"One email a month. Unsubscribe any time.\";}','auto');
